WITH exploded AS (SELECT id, service, host, level, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS attr_key, v) SELECT *, DENSE_RANK() OVER w_grp AS status_code_dense_rank, CUME_DIST() OVER (PARTITION BY host ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_cume_dist, CUME_DIST() OVER w_grp AS status_code_cume_dist FROM exploded WINDOW w_grp AS (ORDER BY status_code DESC);
